import{_ as e,o as a,c as o,ag as r}from"./chunks/framework.B7PviQjB.js";const s="/docs/images/getting-started-contact-list.png",p=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),n={name:"guide/getting-started.md"};function i(d,t,l,h,c,g){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>Sign in, create a sheet, and try each editor in a few minutes.</p><h2 id="sign-in" tabindex="-1">Sign In <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign In&quot;">​</a></h2><p>Go to <a href="https://wafflebase.io" target="_blank" rel="noreferrer">wafflebase.io</a> and click <strong>Sign in</strong>. Use your GitHub account, or Google if the deployment offers it. Your first sign-in creates a workspace for you.</p><h2 id="create-a-sheet-or-document" tabindex="-1">Create a Sheet or Document <a class="header-anchor" href="#create-a-sheet-or-document" aria-label="Permalink to &quot;Create a Sheet or Document&quot;">​</a></h2><p>After signing in, you&#39;ll see your workspace. Click the <strong>New</strong> dropdown button to choose what to create:</p><table tabindex="0"><thead><tr><th>Menu entry</th><th>What it creates</th></tr></thead><tbody><tr><td><strong>New document</strong></td><td>A word-processor-style editor for writing and formatting text</td></tr><tr><td><strong>New sheet</strong></td><td>A spreadsheet for structured data, formulas, and charts</td></tr><tr><td><strong>New presentation</strong></td><td>A slide deck with themes, layouts, and shapes</td></tr><tr><td><strong>New note</strong></td><td>A Markdown editor with a live preview</td></tr><tr><td><strong>New board</strong></td><td>An infinite canvas for sticky notes, shapes, and images</td></tr></tbody></table><p>To bring existing work in, the same menu has a single <strong>Upload files…</strong> entry. Pick as many files as you like. Wafflebase reads each file&#39;s extension and creates the matching document: a spreadsheet from <code>.xlsx</code> or <code>.csv</code>, a document from <code>.docx</code>, a presentation from <code>.pptx</code>, a viewer for a <code>.pdf</code> or an image, and a stored file for anything else. Dragging files onto the documents list does the same thing. See <a href="/docs/guide/import-export.html">Import &amp; Export</a>.</p><p>Inside a workspace the menu also offers <strong>New from template</strong>, <strong>New folder</strong>, and <strong>Import from Miro…</strong>.</p><h2 id="try-a-sheet" tabindex="-1">Try a Sheet <a class="header-anchor" href="#try-a-sheet" aria-label="Permalink to &quot;Try a Sheet&quot;">​</a></h2><p>Select <strong>New sheet</strong> to create a blank spreadsheet, then build a simple contact list. Click on cell <strong>A1</strong> and type the following data, pressing <code>Tab</code> to move right and <code>Enter</code> to move to the next row:</p><table tabindex="0"><thead><tr><th></th><th>A</th><th>B</th><th>C</th></tr></thead><tbody><tr><td>1</td><td><strong>Name</strong></td><td><strong>Email</strong></td><td><strong>Role</strong></td></tr><tr><td>2</td><td>Alice</td><td><a href="mailto:alice@example.com" target="_blank" rel="noreferrer">alice@example.com</a></td><td>Engineer</td></tr><tr><td>3</td><td>Bob</td><td><a href="mailto:bob@example.com" target="_blank" rel="noreferrer">bob@example.com</a></td><td>Designer</td></tr><tr><td>4</td><td>Carol</td><td><a href="mailto:carol@example.com" target="_blank" rel="noreferrer">carol@example.com</a></td><td>Manager</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Press <code>Tab</code> to move to the next column, <code>Enter</code> to move to the next row. Press <code>Escape</code> to cancel editing.</p></div><p>Your spreadsheet should look like this:</p><p><img src="'+s+`" alt="Contact list spreadsheet"></p><h3 id="resize-columns" tabindex="-1">Resize Columns <a class="header-anchor" href="#resize-columns" aria-label="Permalink to &quot;Resize Columns&quot;">​</a></h3><p>If the email column looks cramped, hover over the border between column headers <strong>B</strong> and <strong>C</strong>, then drag it to the right to widen column B.</p><h3 id="add-a-tab" tabindex="-1">Add a Tab <a class="header-anchor" href="#add-a-tab" aria-label="Permalink to &quot;Add a Tab&quot;">​</a></h3><p>Your document starts with one tab called <strong>Sheet1</strong>. Click the <strong>+</strong> button next to the tab bar at the bottom to add a new tab. Double-click the tab name to rename it.</p><h2 id="try-a-document" tabindex="-1">Try a Document <a class="header-anchor" href="#try-a-document" aria-label="Permalink to &quot;Try a Document&quot;">​</a></h2><p>Select <strong>New document</strong> to open a blank page and start typing. Use the toolbar to apply formatting such as <strong>bold</strong>, <em>italic</em>, and text alignment.</p><p>For a full walkthrough, see the <a href="/docs/docs-editor/writing-a-document.html">Writing a Document</a> guide.</p><h2 id="try-a-note" tabindex="-1">Try a Note <a class="header-anchor" href="#try-a-note" aria-label="Permalink to &quot;Try a Note&quot;">​</a></h2><p>Select <strong>New note</strong> for a Markdown editor with a live preview. Type Markdown on the left and watch it render on the right:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Meeting Notes</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] Review the roadmap</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ ] Assign owners</span></span></code></pre></div><p>Switch between <strong>Split</strong>, <strong>Editor</strong>, and <strong>Preview</strong> views from the toolbar. For more, see the <a href="/docs/notes/writing-a-note.html">Writing a Note</a> guide.</p><h2 id="what-s-next" tabindex="-1">What&#39;s Next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next&quot;">​</a></h2><p><strong>Sheets</strong></p><ul><li><a href="/docs/sheets/build-a-budget.html">Build a Budget Spreadsheet</a>: formulas, number formats, and layout in one worked example</li><li><a href="/docs/sheets/formulas.html">Formulas</a>: every supported function</li><li><a href="/docs/sheets/charts.html">Charts &amp; Pivot Tables</a></li><li><a href="/docs/sheets/data-validation.html">Data Validation</a>: checkboxes, dropdowns, and input rules</li><li><a href="/docs/sheets/datasources.html">External Datasources</a>: query a database from a tab</li><li><a href="/docs/sheets/keyboard-shortcuts.html">Keyboard Shortcuts</a></li></ul><p><strong>Docs</strong></p><ul><li><a href="/docs/docs-editor/writing-a-document.html">Writing a Document</a>: text, formatting, tables, and page layout</li><li><a href="/docs/docs-editor/keyboard-shortcuts.html">Keyboard Shortcuts</a></li></ul><p><strong>Slides</strong></p><ul><li><a href="/docs/slides/build-a-deck.html">Build a Deck</a>: a three-slide deck with a theme, a shape, and presentation mode</li><li><a href="/docs/slides/themes-and-layouts.html">Themes &amp; Layouts</a></li><li><a href="/docs/slides/keyboard-shortcuts.html">Keyboard Shortcuts</a></li></ul><p><strong>Notes &amp; Board</strong></p><ul><li><a href="/docs/notes/writing-a-note.html">Writing a Note</a></li><li><a href="/docs/board/using-the-board.html">Using the Board</a></li></ul><p><strong>PDF &amp; Files</strong></p><ul><li><a href="/docs/pdf/viewing-pdfs.html">Viewing PDFs</a>: upload, read, and comment on PDF files</li><li><a href="/docs/pdf/viewing-images.html">Viewing Images</a></li><li><a href="/docs/pdf/organizing-with-folders.html">Organizing with Folders</a></li></ul><p><strong>Common</strong></p><ul><li><a href="/docs/guide/collaboration.html">Collaboration &amp; Sharing</a></li><li><a href="/docs/guide/import-export.html">Import &amp; Export</a>: which formats come in, and what goes out</li></ul>`,39)])])}const u=e(n,[["render",i]]);export{p as __pageData,u as default};
